export const meta = {
  name: 'smartbft-harness-generation',
  description: 'SmartBFT trace harness: verify, regenerate traces, validate against spec',
  phases: [
    { title: 'Verify', detail: 'audit harness files and existing traces' },
    { title: 'Regenerate', detail: 'apply.sh + build + run 4 test scenarios' },
    { title: 'Validate', detail: 'trace validation against Trace.tla for each trace file' },
    { title: 'Report', detail: 'summarize coverage and validation results' },
  ],
}

const SPECULA = '/Users/tess/dev/Specula/case-studies/smartbft/.specula-output'
const REPO = '/Users/tess/dev/Specula/case-studies/smartbft/SmartBFT'

// ── Phase 1: Verify harness artifacts ────────────────────────────────────────
phase('Verify')

const auditResult = await agent(
  `Audit the SmartBFT trace harness artifacts. Check all of the following:

1. Harness files — verify each exists and is non-empty:
   - ${SPECULA}/harness/src/tla_trace.go
   - ${SPECULA}/harness/src/tla_trace_scenarios_test.go
   - ${SPECULA}/harness/apply.sh
   - ${SPECULA}/harness/run.sh
   - ${SPECULA}/harness/INSTRUMENTATION.md
   - ${SPECULA}/harness/patches/instrumentation.patch

2. Trace files — verify each exists and count lines:
   - ${SPECULA}/traces/trace_normal.ndjson
   - ${SPECULA}/traces/trace_view_change.ndjson
   - ${SPECULA}/traces/trace_hb_timeout.ndjson
   - ${SPECULA}/traces/trace_vc_deliver.ndjson

3. For each trace file, parse every line as JSON and:
   - Count valid lines
   - List unique event names and their counts
   - Flag any lines missing "tag":"trace" or "event" field

4. Cross-check coverage: the instrumentation spec defines 12 event types:
   propose, pre_prepare, decide, hb_timeout, change_role, view_change_start,
   vc_deliver, vc_validate, enter_new_view, update_view, update_decisions, vc_same_seq
   — report which event types appear in at least one trace, and which are missing.

5. Check the patch is applicable to the current repo state:
   Run: cd ${REPO} && git diff --stat HEAD internal/bft/controller.go internal/bft/view.go internal/bft/viewchanger.go internal/bft/heartbeatmonitor.go
   This tells us if the files are clean (patch not yet applied) or already patched.

Return a JSON object with fields:
- harness_complete: boolean (all harness files present)
- traces_present: boolean (all 4 trace files present with > 0 lines)
- event_coverage: { covered: string[], missing: string[] }
- repo_state: "clean" | "patched" | "unknown"
- issues: string[] (any problems found)`,
  {
    label: 'audit-harness',
    phase: 'Verify',
    schema: {
      type: 'object',
      properties: {
        harness_complete: { type: 'boolean' },
        traces_present: { type: 'boolean' },
        event_coverage: {
          type: 'object',
          properties: {
            covered: { type: 'array', items: { type: 'string' } },
            missing: { type: 'array', items: { type: 'string' } },
          },
          required: ['covered', 'missing'],
        },
        repo_state: { type: 'string', enum: ['clean', 'patched', 'unknown'] },
        issues: { type: 'array', items: { type: 'string' } },
      },
      required: ['harness_complete', 'traces_present', 'event_coverage', 'repo_state', 'issues'],
    },
  }
)

log(`Audit: harness_complete=${auditResult.harness_complete}, traces_present=${auditResult.traces_present}, covered=${auditResult.event_coverage.covered.length}/12 event types, repo_state=${auditResult.repo_state}`)
if (auditResult.issues.length > 0) {
  log(`Issues found: ${auditResult.issues.join('; ')}`)
}

// ── Phase 2: Regenerate traces ────────────────────────────────────────────────
phase('Regenerate')

const regenResult = await agent(
  `Run the SmartBFT trace harness to regenerate all 4 trace files.
The harness lives at ${SPECULA}/harness/run.sh.

Execute run.sh from the .specula-output/ directory with a generous timeout:
  cd ${SPECULA} && timeout 480 bash harness/run.sh 2>&1

The script will:
1. Reset the repo to clean state (git checkout)
2. Copy tla_trace.go to the repo
3. Apply the instrumentation patch
4. Build the project (go build ./...)
5. Run 4 tests in separate invocations (TestTLATraceNormal, TestTLATraceViewChange, TestTLATraceHBTimeout, TestTLATraceVCDeliver)
6. Report trace line counts

After running, verify:
- Each trace file exists: ${SPECULA}/traces/trace_normal.ndjson, trace_view_change.ndjson, trace_hb_timeout.ndjson, trace_vc_deliver.ndjson
- Count lines in each file using: wc -l ${SPECULA}/traces/*.ndjson
- Check first line of each trace is valid JSON with "tag":"trace"

IMPORTANT: run.sh runs each test with a separate go test -run invocation so the global TLATrace state is isolated per process. Each test has its own -timeout flag (60s for normal/view_change/hb_timeout, 120s for vc_deliver).

Report the full output of run.sh and the line counts. Note any tests that timed out or panicked (those trace files may be empty or partial — still report them).

Return a JSON object:
- success: boolean (run.sh exited without hard failure)
- trace_lines: { normal: int, view_change: int, hb_timeout: int, vc_deliver: int }
- failed_tests: string[] (test names that failed/timed out)
- run_output_summary: string (last 40 lines of run.sh output)`,
  {
    label: 'run-harness',
    phase: 'Regenerate',
    schema: {
      type: 'object',
      properties: {
        success: { type: 'boolean' },
        trace_lines: {
          type: 'object',
          properties: {
            normal: { type: 'number' },
            view_change: { type: 'number' },
            hb_timeout: { type: 'number' },
            vc_deliver: { type: 'number' },
          },
          required: ['normal', 'view_change', 'hb_timeout', 'vc_deliver'],
        },
        failed_tests: { type: 'array', items: { type: 'string' } },
        run_output_summary: { type: 'string' },
      },
      required: ['success', 'trace_lines', 'failed_tests', 'run_output_summary'],
    },
  }
)

log(`Regenerate: success=${regenResult.success}, lines: normal=${regenResult.trace_lines.normal}, vc=${regenResult.trace_lines.view_change}, hb=${regenResult.trace_lines.hb_timeout}, vcdeliver=${regenResult.trace_lines.vc_deliver}`)
if (regenResult.failed_tests.length > 0) {
  log(`Failed tests: ${regenResult.failed_tests.join(', ')}`)
}

// ── Phase 3: Validate traces against spec ─────────────────────────────────────
phase('Validate')

const traceFiles = [
  { name: 'trace_normal', path: `${SPECULA}/traces/trace_normal.ndjson`, lines: regenResult.trace_lines.normal },
  { name: 'trace_view_change', path: `${SPECULA}/traces/trace_view_change.ndjson`, lines: regenResult.trace_lines.view_change },
  { name: 'trace_hb_timeout', path: `${SPECULA}/traces/trace_hb_timeout.ndjson`, lines: regenResult.trace_lines.hb_timeout },
  { name: 'trace_vc_deliver', path: `${SPECULA}/traces/trace_vc_deliver.ndjson`, lines: regenResult.trace_lines.vc_deliver },
].filter(t => t.lines > 0)

log(`Validating ${traceFiles.length} non-empty trace files against spec...`)

const validationResults = await pipeline(
  traceFiles,
  async (traceFile) => {
    const result = await agent(
      `Run TLA+ trace validation for the SmartBFT trace file: ${traceFile.path}

Use the mcp__tracedebugger__run_trace_validation tool to validate this trace file against the SmartBFT spec.

Parameters:
- spec_file: "${SPECULA}/spec/Trace.tla"
- config_file: "${SPECULA}/spec/Trace.cfg"
- trace_file: "${traceFile.path}"
- work_dir: "${SPECULA}/spec/"

The validation will:
1. Load the NDJSON trace
2. Walk through each trace event via TraceNext actions
3. Check that every transition is legal according to the base spec
4. Verify TraceMatched temporal property (entire trace consumed)

After running validation, report:
- Whether validation passed (TLC completed without error)
- If validation failed: the error message, which trace event caused the failure (event index l, event name), and what spec invariant/guard was violated
- The number of trace events successfully consumed before any failure
- Any TLC configuration or spec syntax errors (separate from validation failures)

Return a JSON object:
- trace_name: "${traceFile.name}"
- passed: boolean
- events_consumed: number (how many trace events TLC processed before success or failure)
- error_type: "none" | "validation_failure" | "spec_error" | "tlc_error"
- error_detail: string (empty if passed)
- failed_event_name: string (event name at failure point, empty if passed)
- failed_event_index: number (trace line index at failure, -1 if passed)`,
      {
        label: `validate-${traceFile.name}`,
        phase: 'Validate',
        schema: {
          type: 'object',
          properties: {
            trace_name: { type: 'string' },
            passed: { type: 'boolean' },
            events_consumed: { type: 'number' },
            error_type: { type: 'string', enum: ['none', 'validation_failure', 'spec_error', 'tlc_error'] },
            error_detail: { type: 'string' },
            failed_event_name: { type: 'string' },
            failed_event_index: { type: 'number' },
          },
          required: ['trace_name', 'passed', 'events_consumed', 'error_type', 'error_detail', 'failed_event_name', 'failed_event_index'],
        },
      }
    )
    return result
  }
)

const passed = validationResults.filter(Boolean).filter(r => r.passed)
const failed = validationResults.filter(Boolean).filter(r => !r.passed)

log(`Validation: ${passed.length}/${traceFiles.length} traces passed`)
for (const f of failed) {
  log(`FAILED: ${f.trace_name} at event ${f.failed_event_index} (${f.failed_event_name}): ${f.error_detail.slice(0, 120)}`)
}

// ── Phase 4: Report ───────────────────────────────────────────────────────────
phase('Report')

const reportResult = await agent(
  `Produce a final summary report for the SmartBFT trace harness generation run.

## Audit Results
- Harness complete: ${auditResult.harness_complete}
- Traces present (pre-regen): ${auditResult.traces_present}
- Event coverage (pre-regen): ${auditResult.event_coverage.covered.length}/12 types covered: ${auditResult.event_coverage.covered.join(', ')}
- Missing event types: ${auditResult.event_coverage.missing.length > 0 ? auditResult.event_coverage.missing.join(', ') : 'none'}
- Repo state: ${auditResult.repo_state}
- Audit issues: ${auditResult.issues.length > 0 ? auditResult.issues.join('; ') : 'none'}

## Regeneration Results
- Success: ${regenResult.success}
- Trace line counts: normal=${regenResult.trace_lines.normal}, view_change=${regenResult.trace_lines.view_change}, hb_timeout=${regenResult.trace_lines.hb_timeout}, vc_deliver=${regenResult.trace_lines.vc_deliver}
- Failed tests: ${regenResult.failed_tests.length > 0 ? regenResult.failed_tests.join(', ') : 'none'}

## Validation Results
${validationResults.filter(Boolean).map(r => `- ${r.trace_name}: ${r.passed ? 'PASSED' : 'FAILED'} (${r.events_consumed} events consumed)${r.passed ? '' : ' — ' + r.error_detail.slice(0, 200)}`).join('\n')}

Produce a concise final report covering:
1. Overall harness generation status (COMPLETE / NEEDS_FIXES / FAILED)
2. Event coverage summary
3. Trace file summary
4. Validation pass/fail summary
5. Any issues that need attention
6. Next step recommendation (proceed to Phase 3 validation-workflow, or fix specific issues first)

Keep it under 400 words. Be specific about what works and what doesn't.`,
  { label: 'final-report', phase: 'Report' }
)

return {
  audit: auditResult,
  regen: regenResult,
  validation: validationResults.filter(Boolean),
  report: reportResult,
}

